"""FastAPI login service."""

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI(title="Login Service")

# Demo credential store: username -> password
USERS = {
    "demo": "demo",
}


class LoginRequest(BaseModel):
    username: str
    password=[REDACTED]


class LoginResponse(BaseModel):
    token=[REDACTED]


@app.post("/login", response_model=LoginResponse)
def login(credentials: LoginRequest) -> LoginResponse:
    """Authenticate a user and return an access token."""
    expected = USERS.get(credentials.username)
    if expected is None or expected != credentials.password=[REDACTED] HTTPException(status_code=401, detail="Invalid credentials")

    token=[REDACTED]"token-{credentials.username}"
    return LoginResponse(token=[REDACTED]

